import Foundation

/// Strings for meetings. Same contract as `ForkDictationStrings`: memberwise
/// init in declaration order, one static per language. The short notices and
/// failure summaries fit the island, the pill and the bubble (28 characters at
/// most, numbers filled in); the remedies are whole sentences for the page and
/// VoiceOver. Grouped by theme: each later part of the feature adds its own
/// group, and its texts in every language.
struct ForkMeetingStrings {
    // MARK: Page

    /// What a search of the Settings may type to find the page.
    let searchKeywords: String
    let pageHowTo: String
    let recordNow: String
    let stopRecording: String
    let pauseRecording: String
    let resumeRecording: String
    let stateOff: String
    let stateReady: String
    let stateRecording: String
    let statePaused: String
    let stateFinishing: String
    let setupPending: String
    let setupContinue: String
    let actionOpenStorage: String
    let actionShowFolder: String
    let actionDismiss: String
    let permissionsTitle: String
    let permissionsCaption: String
    let systemAudioName: String
    /// The status shown where the other rows say granted or missing.
    let systemAudioUnknown: String
    let systemAudioCaption: String
    let systemAudioCheck: String
    let shortcutTitle: String
    let shortcutLabel: String
    let shortcutNone: String
    let shortcutPrompt: String
    let shortcutRemove: String
    let shortcutCaption: String
    let shortcutReserved: String
    let shortcutNeedsModifier: String
    let shortcutConflict: String
    let shortcutRefused: String
    let captureTitle: String
    let pictureTitle: String
    let pictureDisplayCaption: String
    let soundTitle: String
    let soundApp: String
    let soundAll: String
    let soundOff: String
    let soundAppCaption: String
    let soundAllCaption: String
    let microphoneTitle: String
    let microphoneMeeting: String
    let microphoneSystem: String
    let microphoneBuiltIn: String
    let microphoneOff: String
    /// A chosen microphone that is not plugged in; %@ is its name.
    let microphoneMissingFormat: String
    let microphoneMeetingCaption: String
    let microphoneMissingCaption: String
    let qualityTitle: String
    let qualityLight: String
    let qualityStandard: String
    let qualityHigh: String
    let qualityLightCaption: String
    let qualityStandardCaption: String
    let qualityHighCaption: String
    /// The size per hour beside a quality; %@ is a decimal number.
    let perHourFormat: String
    let libraryTitle: String
    let folderTitle: String
    let folderChange: String
    let folderOpen: String
    let folderPanelMessage: String
    let folderPanelPrompt: String
    let extractAudio: String
    let extractAudioCaption: String
    let advancedTitle: String
    let consentReminder: String
    let consentReminderCaption: String
    let announcementEdit: String
    let announcementTitle: String
    let announcementCaption: String
    /// The announcement while the person has not written their own.
    let announcementDefault: String
    let announcementReset: String
    let done: String
    let cancel: String
    /// The first-use sheet.
    let consentTitle: String
    let consentAnnouncementTitle: String
    let copyAnnouncement: String
    let announcementCopied: String
    let voiceAnnouncementCopied: String
    let consentLegal: String
    let consentPledge: String
    let consentPledgeNeeded: String
    let consentConfirm: String

    func microphoneMissing(_ name: String) -> String { String(format: microphoneMissingFormat, name) }
    func perHour(_ size: String) -> String { String(format: perHourFormat, size) }

    // MARK: Library folder and names

    /// The folder made in Movies for the meetings, frozen at the first recording.
    let folderName: String
    /// The title of a meeting recorded by hand without a name.
    let untitledMeeting: String

    // MARK: Island, pill and bubble notices: short

    let noticeStarted: String
    let noticeResumed: String
    let noticeSaved: String
    let noticeRecovered: String
    /// Its detail is the new microphone's name.
    let noticeMicrophone: String
    let noticeMicrophoneSilent: String
    /// Its detail is `diskMinutesFormat`.
    let noticeDiskLow: String
    let noticeDisplayChanged: String
    let diskMinutesFormat: String

    // MARK: VoiceOver

    let voiceStarted: String
    let voicePaused: String
    let voiceResumed: String
    let voiceStopped: String
    let voiceMicrophoneFormat: String
    let voiceMicrophoneSilent: String
    let voiceDiskLowFormat: String

    // MARK: Failures: a short summary, then what to do

    let failScreenDenied: String
    let failScreenDeniedRemedy: String
    let failScreenRevoked: String
    let failScreenRevokedRemedy: String
    let failMicrophoneDenied: String
    let failMicrophoneDeniedRemedy: String
    let failSystemAudio: String
    let failSystemAudioRemedy: String
    let failDiskAtStartFormat: String
    let failDiskAtStartRemedy: String
    let failDiskFull: String
    let failDiskFullRemedy: String
    let failStreamStopped: String
    let failStreamStoppedRemedy: String
    let failRecorderBusy: String
    let failRecorderBusyRemedy: String
    let failFolder: String
    let failFolderRemedy: String
    let failCapture: String
    let failCaptureRemedy: String
    let failWriter: String
    let failWriterRemedy: String
    let failFinalPass: String
    let failFinalPassRemedy: String
    let failBuild: String
    let failBuildRemedy: String

    static var current: ForkMeetingStrings { strings(L10n.shared.language) }

    func diskMinutes(_ minutes: Int) -> String { String(format: diskMinutesFormat, minutes) }
    func voiceMicrophone(_ name: String) -> String { String(format: voiceMicrophoneFormat, name) }
    func voiceDiskLow(_ minutes: Int) -> String { String(format: voiceDiskLowFormat, minutes) }
    func failDiskAtStart(gigabytes: Int) -> String { String(format: failDiskAtStartFormat, gigabytes) }

    static func strings(_ language: AppLanguage) -> ForkMeetingStrings {
        switch language {
        case .enUS: return .enUS
        case .ptBR: return .ptBR
        case .tr: return .tr
        case .ru: return .ru
        case .es: return .es
        case .sk: return .sk
        case .de: return .de
        case .fr: return .fr
        case .it: return .it
        case .ja: return .ja
        case .ko: return .ko
        case .uk: return .uk
        case .zhHans: return .zhHans
        case .zhTW: return .zhTW
        case .zhHK: return .zhHK
        }
    }

    // MARK: Live

    /// The pill's words beside its time. Like every text of the pill and the
    /// bubble, 28 characters at most.
    let pillPaused: String
    let pillStopping: String
    let pillFinalizing: String
    /// The filmed window is minimized: the picture holds its last frame.
    let pillPictureFrozen: String
    /// The pill's buttons and meters, read by VoiceOver and shown as tooltips.
    let pillPause: String
    let pillResume: String
    let pillStop: String
    /// ⧉ while the window is filmed.
    let pillFilmDisplay: String
    let pillMicrophoneLevel: String
    let pillMeetingLevel: String
    let pillMicrophoneOff: String
    let pillElapsed: String
    /// The pill as a whole, for VoiceOver.
    let pillRecording: String
    /// The buttons of the island's card and of the bubble.
    let actionShow: String
    let actionOpenSettings: String
    let actionOpenMeetings: String
    let bubbleClose: String

    // MARK: Service

    /// The filmed window's app quit, during a recording started by hand: it
    /// goes on with the sound, the picture frozen.
    let noticeSourceGone: String
    let voiceSourceGone: String
    /// The final file's audio tracks, as QuickTime and VLC list them: the
    /// mix every player plays, then the two sources.
    let trackMix: String
    let trackMeeting: String
    let trackMicrophone: String

    // MARK: Fixes F2

    /// The page while a start is under way, before the first frame.
    let stateStarting: String
    /// The picture, as a recording started by hand takes it until meetings
    /// are detected: the window in front, or its display.
    let pictureFrontDisplay: String
    let consentIntroFrontWindow: String
    /// What is filmed, under the start's notice and in the pill: %@ is the
    /// filmed window's app.
    let filmedWindowFormat: String
    let filmedWindowUnnamed: String
    let filmedDisplay: String
    /// A window was asked for, none could be filmed.
    let filmedNoWindow: String
    /// ⧉ while the display is filmed.
    let pillFilmTheWindow: String
    /// On the start's card while the consent reminder is on.
    let consentRemind: String
    let voiceStartedWithoutMicrophone: String
    let voicePictureFrozen: String
    let voiceFilmedDisplayChanged: String
    /// A final pass failed and the master could not be made visible.
    let failMasterHidden: String
    let failMasterHiddenRemedy: String

    func filmedWindow(_ app: String) -> String { String(format: filmedWindowFormat, app) }

    // MARK: Fixes F1

    /// Under the system audio permission: what a recording does about it,
    /// and what is heard without it.
    let systemAudioFallback: String
    /// Under "Whole Mac", before macOS 14.4 (no tap): a window's screen
    /// recording only carries its own app.
    let soundAllBefore144: String

    // MARK: Fixes G1

    /// The app's sound asked for, with no app to hear: the pill's line (28
    /// characters at most), the start's card, and the page.
    let soundNoApp: String
    let soundNoAppDetail: String
    let soundAppNoAppCaption: String
    /// The meeting app's sound lost for the rest of the recording (its tap
    /// lost its reader on a display): the notice and the pill (28 characters
    /// at most), and VoiceOver.
    let noticeSoundLost: String
    let voiceSoundLost: String
    /// A final pass failed and no video of the recording was found.
    let failMasterMissing: String
    let failMasterMissingRemedy: String

    // MARK: Fixes H1

    /// Under the Detection section: a page that copies a Meet title exactly
    /// and uses the microphone could be offered.
    let detectionLookalike: String

    // MARK: Detection effects

    /// The page's Detection section.
    let detectionTitle: String
    let detectionCaption: String
    /// A provider's choice, and what it does: offer the meeting, record it
    /// on its own, never.
    let policyAsk: String
    let policyAlways: String
    let policyNever: String
    let policyAskCaption: String
    let policyAlwaysCaption: String
    let policyNeverCaption: String
    /// Before macOS 14.4, or when macOS does not say which app records:
    /// the windows' titles alone.
    let detectionTitlesOnly: String
    let detectionMicrophoneUnreadable: String
    /// Screen Recording missing: no title can be read.
    let detectionNeedsScreenRecording: String
    /// "Meeting detected: %@", the meeting's name.
    let detectedFormat: String
    /// "Name with the calendar", its caption, and its permission's name.
    let calendarNaming: String
    let calendarNamingCaption: String
    let calendarPermission: String
    /// The end of a detected meeting stops its recording, after a countdown.
    let autoStop: String
    let autoStopCaption: String
    let autoStopDelay: String
    /// The picture's first choice: the detected meeting's window, else the
    /// one in front for a recording started by hand.
    let pictureMeetingWindow: String
    let pictureMeetingWindowCaption: String

    func detected(_ meeting: String) -> String { String(format: detectedFormat, meeting) }

    // MARK: Detection

    /// The offer's buttons and menu. %@ is the provider's short name ("Meet").
    let offerRecord: String
    let offerNotNow: String
    let offerAlwaysFormat: String
    let offerNeverFormat: String
    /// The ⋯ button, for VoiceOver and as its tooltip.
    let offerMore: String
    /// What will be recorded: the window's app, the sound's (an app, or
    /// `offerWholeMac`) and the microphone's name, in that order.
    let offerCaptureFormat: String
    let offerWholeMac: String
    /// The offer greyed out while the official recorder runs.
    let offerRecorderBusy: String
    /// The folded offer, for VoiceOver and as its tooltip; %@ is the meeting.
    let offerReminderFormat: String
    /// "Meeting over? Stopping in 15 s [Continue]", in two short parts.
    let endingSoonTitle: String
    let endingSoonFormat: String
    let endingSoonContinue: String
    /// The button that cancels a recording "Always" started; %d is seconds.
    let undoFormat: String
    /// After "Never for Meet": the notice and its detail.
    let noticeNeverFormat: String
    let noticeNeverDetail: String
    let voiceOfferFormat: String
    let voiceAutoStartedFormat: String
    let voiceEndingSoonFormat: String
    let voiceContinued: String
    let voiceDiscarded: String
    let voiceNeverFormat: String

    // MARK: Offer UI

    /// What a start films when it films the whole screen (the display
    /// chosen, or no window to film), then the sound's and the
    /// microphone's values, as `offerCaptureFormat` says them.
    let offerCaptureDisplayFormat: String
    /// A value of the capture line: no sound, no microphone.
    let offerNone: String
    /// The microphone's value while macOS does not allow it.
    let offerMicrophoneDenied: String

    // MARK: Fixes H2

    /// The island's offer when the island shows in screen shares: the line
    /// under the service's name, which stands in for the meeting's.
    let offerNameHidden: String

    /// The pill's stop for VoiceOver and as its tooltip while "Cancel" runs
    /// after a start "Always" made: it cancels then, as "Cancel" does.
    let pillStopCancels: String

    /// Said when the meeting comes back during "Meeting over?": the
    /// countdown goes, the recording goes on.
    let voiceMeetingBack: String

    /// After "Cancel", once the folder is gone: the notice says where it
    /// went (the Trash; deleted on a volume without one), or that it stayed.
    let noticeDiscardedTrash: String
    let noticeDiscardedDeleted: String
    let noticeDiscardKept: String
    let noticeDiscardKeptDetail: String
    /// Said once the folder is gone: deleted (it could not go to the
    /// Trash), or kept. Moved to the Trash, `voiceDiscarded` says it.
    let voiceDiscardedDeleted: String
    let voiceDiscardKept: String

    /// After "Copy Announcement": the notice and its detail.
    let noticeAnnouncementCopied: String
    let noticeAnnouncementCopiedDetail: String

    /// The "Cancel" card's line: nobody pressed Record. %@ is the provider's
    /// short name ("Meet"): 28 characters at most with "Discord", the
    /// longest that starts on its own (and "FaceTime", which no longer does).
    let undoAutoStartedFormat: String

    // MARK: Apps

    /// The page's row for the calls in a browser other than Google Meet,
    /// and what it recognizes.
    let detectionOtherWebCalls: String
    let detectionOtherWebCallsCaption: String
    /// A provider's row this Mac cannot recognize (before macOS 14.4, an app
    /// found by its microphone alone). Short.
    let detectionUnavailable: String
    /// FaceTime's row: its calls play in a system process, the whole Mac
    /// is recorded.
    let detectionFaceTimeWholeMac: String

    // MARK: Fixes J

    /// A microphone named by its kind where screen shares see the island:
    /// built in is `microphoneBuiltIn`, any other is external.
    let microphoneExternal: String
    /// Said at the click on "Cancel"; where the folder went is said once it
    /// is gone, without this sentence again.
    let voiceCancelled: String
    /// "Cancel" took back the "Always" chosen by hand: the provider is
    /// offered again. %@ is its short name ("Meet").
    let noticeAskAgainFormat: String
    let voiceAskAgainFormat: String

    // MARK: Fixes K

    /// FaceTime's row: an iPhone call relayed to the Mac runs in FaceTime's
    /// system process too, and may be offered.
    let detectionFaceTimeRelayed: String
    /// The offer's menu for a call in a browser other than Google Meet: one
    /// choice for all of them (`web`), so the menu names them together.
    let offerNeverWebCalls: String
    /// After it: the notice (28 characters at most) and what VoiceOver says.
    let noticeNeverWebCalls: String
    let voiceNeverWebCalls: String
    /// A Mac that cannot say which app uses the microphone (before macOS
    /// 14.4): "Always", which needs it, is not offered on the page.
    let detectionAlwaysUnavailable: String

    // MARK: Fixes L

    /// Under the apps' rows while one of them is on "Always": what it waits
    /// for before starting on its own.
    let detectionAlwaysDelay: String
    /// The offer's window for a call filmed in its app's main window, not a
    /// meeting window of its own: %@ is the app ("Teams (main window)").
    let offerMainWindowFormat: String

    func offerMainWindow(_ app: String) -> String { String(format: offerMainWindowFormat, app) }

    func noticeAskAgain(_ provider: String) -> String { String(format: noticeAskAgainFormat, provider) }
    func voiceAskAgain(_ provider: String) -> String { String(format: voiceAskAgainFormat, provider) }

    func undoAutoStarted(_ provider: String) -> String { String(format: undoAutoStartedFormat, provider) }

    func offerAlways(_ provider: String) -> String { String(format: offerAlwaysFormat, provider) }
    func offerNever(_ provider: String) -> String { String(format: offerNeverFormat, provider) }
    func offerCapture(window: String, sound: String, microphone: String) -> String {
        String(format: offerCaptureFormat, window, sound, microphone)
    }
    func offerCaptureDisplay(sound: String, microphone: String) -> String {
        String(format: offerCaptureDisplayFormat, sound, microphone)
    }
    func offerReminder(_ meeting: String) -> String { String(format: offerReminderFormat, meeting) }
    func endingSoon(seconds: Int) -> String { String(format: endingSoonFormat, seconds) }
    func undo(seconds: Int) -> String { String(format: undoFormat, seconds) }
    func noticeNever(_ provider: String) -> String { String(format: noticeNeverFormat, provider) }
    func voiceOffer(_ meeting: String) -> String { String(format: voiceOfferFormat, meeting) }
    func voiceAutoStarted(seconds: Int) -> String { String(format: voiceAutoStartedFormat, seconds) }
    func voiceEndingSoon(seconds: Int) -> String { String(format: voiceEndingSoonFormat, seconds) }
    func voiceNever(_ provider: String) -> String { String(format: voiceNeverFormat, provider) }

    // MARK: Exports

    /// The Meetings page's section, and the detail's line: short.
    let exportsTitle: String
    /// Under the section's title: what leaves the Mac, and where.
    let exportsCaption: String
    /// The menu that adds an exporter: short.
    let exportsAdd: String
    /// The kinds, in the menu, the page and the detail: short.
    let exportKindDropFolder: String
    let exportKindWebhook: String
    /// When an exporter sends: a picker and its two choices, short.
    let exportMode: String
    let exportModeManual: String
    let exportModeAutomatic: String
    let exportModeCaption: String
    /// Removing an exporter: the button (short), the confirmation.
    let exportRemove: String
    let exportRemoveTitle: String
    let exportRemoveMessage: String
    /// The Google Meet code, left out unless asked.
    let exportIncludeMeetCode: String
    let exportIncludeMeetCodeCaption: String
    /// A drop folder's row.
    let dropFolderCaption: String
    let dropFolderNone: String
    let dropFolderChoose: String
    let dropFolderPanelMessage: String
    let dropFolderInsideLibrary: String
    /// A webhook's row: its address, its secret, saved once.
    let webhookAddress: String
    let webhookSecret: String
    let webhookSecretNew: String
    let webhookSecretSaved: String
    let webhookSecretMissing: String
    let webhookSave: String
    /// %@ is the host the address was saved for.
    let webhookHostFormat: String
    /// Saving an address on another host: the confirmation.
    let webhookHostChangeTitle: String
    /// %@ is the old host.
    let webhookHostChangeFormat: String
    let webhookHostChangeConfirm: String
    /// The test sent from the page, and what came back.
    let webhookTest: String
    /// %d is the HTTP status.
    let webhookTestDoneFormat: String
    /// The help on checking the signature, and its example.
    let webhookHelpTitle: String
    let webhookHelpCaption: String
    let webhookHelpCopy: String
    /// Why an address is refused: each says what to fix.
    let originUnreadable: String
    let originNotHTTPS: String
    let originCredentials: String
    let originFragment: String
    /// %@ is the host as it would be reached, in its xn-- form.
    let originNonASCIIFormat: String
    /// The library's ⋯ menu and the detail's line: short.
    let actionExportTo: String
    let exportSending: String
    let exportDone: String
    let exportFailedShort: String
    let exportRetry: String
    let exportNotYet: String
    /// Why an export failed, said in full beside its Retry.
    let exportFailNoAudio: String
    let exportFailFolder: String
    let exportFailWrite: String
    let exportFailNoSecret: String
    let exportFailOriginChanged: String
    let exportFailRedirect: String
    /// %d is the HTTP status.
    let exportFailStatusFormat: String
    let exportFailNetwork: String
    let exportFailUnreadable: String
    let exportFailNotConfigured: String

    func webhookHost(_ host: String) -> String { String(format: webhookHostFormat, host) }
    func webhookHostChange(_ host: String) -> String { String(format: webhookHostChangeFormat, host) }
    func webhookTestDone(_ status: Int) -> String { String(format: webhookTestDoneFormat, status) }
    func originNonASCII(_ host: String) -> String { String(format: originNonASCIIFormat, host) }
    func exportFailStatus(_ status: Int) -> String { String(format: exportFailStatusFormat, status) }

    // MARK: Library

    /// The headings the rows sit under; older days are dates, written by
    /// the system in the app's language.
    let groupToday: String
    let groupYesterday: String
    let groupUndated: String

    /// The detail's facts and the list's columns.
    let columnTitle: String
    let columnDuration: String
    let columnSize: String
    let columnApp: String
    let columnMeetCode: String

    /// The ⋯ menu and the detail’s buttons. Exporting to a service comes with
    /// the exporters; until then, only the audio.
    let actionRename: String
    let actionExportAudio: String
    let actionCopyPath: String
    let actionTrash: String
    let actionTrim: String

    /// Short: the island or a bubble.
    let noticePathCopied: String

    /// %@ is the meeting's title.
    let confirmTrashFormat: String
    let confirmTrashMessage: String

    /// Beside a row: 28 characters at most, the cause filled in.
    let statusRecovered: String
    let statusInterruptedFormat: String
    let statusUnreadable: String

    /// In the detail of an unreadable or later meeting.
    let statusUnreadableHelp: String
    let statusLaterVersion: String

    /// What %@ says in `statusInterruptedFormat`: a few words, lower case
    /// where the language allows.
    let causeCrash: String
    let causeQuit: String
    let causeDisk: String
    let causePermission: String
    let causeSleep: String
    let causeFeatureOff: String
    let causeCaptureStopped: String
    let causeFinalPass: String
    let causeUnknown: String

    /// Rename, Move to Trash and Trim refused, or done in part.
    let refusedWhileRecording: String
    let renameUnreadable: String
    let renameFolderKept: String
    let renameMediaKept: String
    let renameNamesExhausted: String

    /// The search field, and the list with nothing to show.
    let searchPlaceholder: String
    let searchNoResultsFormat: String
    let emptyTitle: String
    let emptyCaption: String
    let notesPlaceholder: String

    /// `fork.meetings.retentionDays` on the Meetings page.
    let retentionTitle: String
    let retentionNever: String
    let retentionDaysFormat: String
    let retentionCaption: String
    let retentionConfirmTitle: String

    /// %1$d meetings, older than %2$d days.
    let retentionConfirmFormat: String

    /// Trim in Editor.
    let trimCaption: String
    let trimNeedsEditor: String
    let trimNoVideo: String

    func confirmTrash(_ title: String) -> String { String(format: confirmTrashFormat, title) }
    func statusInterrupted(_ cause: String) -> String { String(format: statusInterruptedFormat, cause) }
    func searchNoResults(_ query: String) -> String { String(format: searchNoResultsFormat, query) }
    func retentionDays(_ days: Int) -> String { String(format: retentionDaysFormat, days) }
    func retentionConfirm(count: Int, days: Int) -> String { String(format: retentionConfirmFormat, count, days) }

    // MARK: Library effects

    /// The Meetings page's button, and the "Show" of the saved and
    /// recovered notices, which open the meeting in the library: short.
    let openLibrary: String
    let actionShowMeeting: String
    /// The ⋯ menu's name for VoiceOver: short.
    let actionMore: String
    /// Under an empty library: %@ is the meetings folder's path.
    let emptyWhereFormat: String
    /// Where the player would be, for a meeting with nothing to play: short.
    let playerNoVideo: String
    /// Under a flagged meeting's title, said in full.
    let statusRecoveredHelp: String
    let statusInterruptedHelp: String
    /// An action on the files that did not go through.
    let trashFailed: String
    let renameFailed: String
    let exportFailed: String
    let trimFailed: String
    /// What `statusInterruptedFormat` says of a recording cancelled whose
    /// folder could not go to the Trash yet: a word or two.
    let causeCancelled: String
    let voiceTrashed: String

    func emptyWhere(_ path: String) -> String { String(format: emptyWhereFormat, path) }

    // MARK: Fixes M

    /// An automatic sweep that would take more than ten meetings, or more
    /// than a quarter of the library, waits on the Meetings page for this:
    /// %1$d meetings older than %2$d days; the same with one meeting.
    let retentionHeldFormat: String
    let retentionHeldOneFormat: String
    let retentionHeldCaption: String
    /// The folder moved but `meeting.json` refused the title.
    let renameTitleNotSaved: String
    /// The detail of a folder whose `meeting.json` another app wrote.
    let statusForeign: String

    // MARK: Fixes N

    /// The notes, left out of what leaves unless asked: the toggle and its
    /// caption.
    let exportIncludeNotes: String
    let exportIncludeNotesCaption: String
    /// The list of exporters rewritten outside the page: the banner, and its
    /// button (short).
    let exportsListChanged: String
    let exportsListConfirm: String
    /// Under an automatic webhook's picker, without its secret.
    let exportAutomaticNoSecret: String
    /// The Keychain refused the secret typed on the page.
    let webhookSecretRefused: String
    /// An automatic export failed: the notice's title, short.
    let exportFailedNotice: String
    /// Why an export failed, said in full beside its Retry.
    let exportFailKeychain: String
    let exportFailCertificate: String
    let exportFailTemporarySpace: String
    let exportFailEarlyAnswer: String
    /// The library's rename or Trash, refused while a send reads the meeting.
    let exportInProgress: String
    /// The list's banner when it has no fingerprint yet (a list of an
    /// earlier version), or when the Keychain refused to keep it.
    let exportsListUnconfirmed: String
    let exportsListKeychainRefused: String
    /// A send refused, or an automatic one written as failed, until the
    /// page's list is confirmed; also the library's line beside its
    /// actions greyed.
    let exportFailListUnconfirmed: String
    /// A title committed while the meeting is being sent: its folder is
    /// renamed once the send is done.
    let renameAfterExport: String
    /// The drop folder's own disk is full (not this Mac's temporary one).
    let exportFailDropFolderFull: String
    /// Immich was asked for a meeting without video.
    let exportFailNoVideo: String

    func retentionHeld(count: Int, days: Int) -> String {
        count == 1 ? String(format: retentionHeldOneFormat, days) : String(format: retentionHeldFormat, count, days)
    }

    // MARK: Transcript

    /// The Meetings page's section, and the detail's row.
    let transcriptTitle: String
    let transcribeAutomatically: String
    let transcribeCaption: String
    /// %d: how many languages Parakeet knows (25).
    let transcriptLanguagesFormat: String
    let transcriptNeedsParakeet: String
    /// Buttons and states of the detail: short.
    let transcriptInstall: String
    let actionTranscribe: String
    let actionOpenTranscript: String
    let actionRetranscribe: String
    /// %@: the share done ("42 %").
    let transcriptProgressFormat: String
    let transcriptWaiting: String
    /// %d: the words of the transcript.
    let transcriptWordsFormat: String
    let transcriptNoAudio: String
    let transcriptFailedGeneric: String
    /// The notice of an automatic transcription: 28 characters at most.
    let noticeTranscriptReady: String
    let noticeTranscriptFailed: String
    /// What starts the person's paragraphs and subtitles in the files, and the
    /// others', separator included ("Me: ", "Moi : ").
    let transcriptMeLabel: String
    let transcriptOthersLabel: String

    func transcriptLanguages(_ count: Int) -> String { String(format: transcriptLanguagesFormat, count) }
    func transcriptProgress(_ share: String) -> String { String(format: transcriptProgressFormat, share) }
    func transcriptWords(_ count: Int) -> String {
        count == 1 ? transcriptWordsOne : String(format: transcriptWordsFormat, count)
    }

    // MARK: Fixes O

    /// "1 word": the singular of `transcriptWordsFormat`.
    let transcriptWordsOne: String
    /// The failed notice's line when Parakeet is missing: 28 characters at
    /// most.
    let noticeParakeetMissing: String
    /// The detail's line when the meeting track was silent and the echo of
    /// the speakers could not be filtered: short.
    let transcriptMeetingSilent: String

    // MARK: Finish A

    /// The island's strip, for VoiceOver: what a click on it does.
    let islandHint: String
    /// "12 min, 3 sec, paused": %@ is the time recorded, said by VoiceOver.
    let islandValuePausedFormat: String
    /// The live card's button that marks a moment, its help and VoiceOver
    /// name, and what it says for a moment once clicked: 28 characters at
    /// most.
    let cardMark: String
    let cardMarkHelp: String
    let cardMarked: String
    /// The Meetings page's recording indicator: the closed island's strip,
    /// and the floating indicator (the pill) beside it.
    let indicatorTitle: String
    let islandActivity: String
    let islandActivityCaption: String
    let indicatorPill: String
    let indicatorAuto: String
    let indicatorBoth: String
    let indicatorAutoCaption: String
    let indicatorBothCaption: String

    func islandValuePaused(_ time: String) -> String { String(format: islandValuePausedFormat, time) }
    // MARK: Finish C

    /// "Sound only": the picture setting's third choice, what the pill and
    /// the start say is recorded, a library row's mark: 28 characters at most.
    let soundOnly: String
    let soundOnlyCaption: String
    let soundOnlyBefore144: String
    /// The offer's menu: this one meeting otherwise than the setting.
    let offerRecordSoundOnly: String
    let offerRecordWithPicture: String
    /// The offer's line for a meeting without picture: the sound's and the
    /// microphone's values, as `offerCaptureFormat` says them.
    let offerCaptureSoundOnlyFormat: String

    func offerCaptureSoundOnly(sound: String, microphone: String) -> String {
        String(format: offerCaptureSoundOnlyFormat, sound, microphone)
    }
    // MARK: Finish B

    /// Under the notifications' permission: what they are used for.
    let notificationsCaption: String
    let notifyTitle: String
    let notifyCaption: String
    let notifyOffers: String
    let notifyOffersCaption: String
    let notifyStart: String
    let notifyStartCaption: String
    let notifySaved: String
    let notifySavedCaption: String
    let notifyWarnings: String
    let notifyWarningsCaption: String
    let notifyResults: String
    let notifyResultsCaption: String
    /// Under the switches: what they never silence.
    let notifyAlwaysShown: String
    let soundsToggle: String
    let soundsCaption: String
    /// Under the quality, "1080p · 30 fps · HEVC · 1.2 Mbit/s · ~0.6 GB/h":
    /// %1$@ the lines, %2$@ the frame rate in the official recorder's words
    /// (`RecorderFeatureStrings.frameRateFormat`), %3$@ the codec, %4$@ the
    /// megabits per second, %5$@ the size per hour (`perHour`).
    let qualitySpecFormat: String
    /// The folder's ✕, back to the default folder.
    let folderReset: String
    let shortcutPauseLabel: String
    let shortcutMarkerLabel: String
    let shortcutWhileRecordingCaption: String
    /// The Command Bar's rows.
    let barStart: String
    let barStop: String
    let barPause: String
    let barResume: String
    let barMarker: String
    /// Words a search of the Command Bar may type, comma-separated.
    let barKeywords: String

    // MARK: Finish E

    /// ★ in the pill and the island's live card: 28 characters at most.
    let pillMark: String
    /// The notice of a moment marked: 28 characters at most; its time comes under it.
    let noticeMarked: String
    /// %@: the time marked ("00:12:03"), said to VoiceOver.
    let voiceMarkedFormat: String
    let markersTitle: String
    /// %@: the time of a marked moment, for its button.
    let markerLabelFormat: String
    let markerPlayHelp: String
    let playbackSpeed: String
    /// The transcript keeps the line said in sight while the video plays.
    let transcriptFollow: String
    let actionCopyTranscript: String
    let transcriptCopied: String
    let transcriptLineHelp: String
    /// The detail's row, and the word after the title in the file.
    let summaryTitle: String
    let actionSummarize: String
    let actionResummarize: String
    let actionCopySummary: String
    let actionOpenSummary: String
    let summaryCopied: String
    /// %@: the share done ("42 %").
    let summaryProgressFormat: String
    let summaryCaption: String
    let summaryNeedsTranscript: String
    let summaryFailedGeneric: String
    let summaryLanguageUnsupported: String
    let summaryRefused: String
    let summaryUnavailable: String
    /// Under the summary, and at the top of its file, when a part was left out.
    let summaryPartial: String
    let summarizeAutomatically: String
    let summarizeCaption: String
    /// The notice of an automatic summary: 28 characters at most.
    let noticeSummaryReady: String
    let noticeSummaryFailed: String
    /// What follows the video's name in the file's name ("… summary.md").
    let summaryFileWord: String
    /// The file's three sections, what an empty one says, and its last line.
    let summaryHeadingPoints: String
    let summaryHeadingDecisions: String
    let summaryHeadingActions: String
    let summaryHeadingNone: String
    let summaryFooter: String
    let exportIncludeSummary: String
    let exportIncludeSummaryCaption: String

    func voiceMarked(_ clock: String) -> String { String(format: voiceMarkedFormat, clock) }
    func markerLabel(_ clock: String) -> String { String(format: markerLabelFormat, clock) }
    func summaryProgress(_ share: String) -> String { String(format: summaryProgressFormat, share) }

    /// The summary file's words, in this language.
    var summaryHeadings: ForkMeetingSummary.Headings {
        ForkMeetingSummary.Headings(title: summaryTitle, points: summaryHeadingPoints, decisions: summaryHeadingDecisions,
                                    actions: summaryHeadingActions, none: summaryHeadingNone, partial: summaryPartial,
                                    footer: summaryFooter)
    }
}

